  "your starting point every time you sign in - a live, company-wide snapshot, never a fixed report.": "সাইন ইন করার পর এখান থেকে কাজ শুরু করুন। এতে কোম্পানির সর্বশেষ হিসাব ও কার্যক্রম দেখা যায়।",
  "the company-wide command center - every number here is computed live from real records (units, sales, payments, expenses...) every time you load the page, never a fixed report or a typed-in figure.": "কোম্পানির সার্বিক কাজের ড্যাশবোর্ড। প্রতিবার পেজ খুললে ইউনিট, বিক্রয়, পেমেন্ট ও ব্যয়সহ নথিভুক্ত তথ্য থেকে হিসাব হয়।",
  "\"urgent\" and \"today\" at the top show your most time-sensitive alerts and reminders - click through to act on them immediately.": "ওপরের ‘জরুরি’ ও ‘আজ’ অংশ থেকে সময়সীমা ঘনিয়ে আসা সতর্কতা ও স্মরণিকা খুলুন।",
  "every kpi card is clickable - it takes you straight to the underlying list or report (e.g. click \"outstanding\" to see exactly which owners owe money).": "হিসাবের কার্ডে ক্লিক করলে বিস্তারিত খুলবে। যেমন ‘বকেয়া’ থেকে কার কাছে কত পাওনা দেখুন।",
  "recent activity shows the latest real actions across the whole system; quick actions gives one-click shortcuts to the most common tasks.": "‘সাম্প্রতিক কার্যক্রমে’ সর্বশেষ কাজ দেখুন। ‘দ্রুত কাজ’ থেকে নিয়মিত কাজ এক ক্লিকে খুলুন।",
  "a small red dot on a sidebar item (projects, sales, settings, etc.) means that section is still empty or missing key info - it disappears the moment you add something there, so it's a running checklist of what's left to set up, not an alert about a problem.": "সাইডবারের ছোট লাল বিন্দু দেখালে ওই বিভাগে প্রয়োজনীয় তথ্য যোগ করা বাকি। তথ্য যোগ করলে বিন্দুটি সরে যায়।",
  "tick one client or many. choose a project to see only its customers, then select all.": "এক বা একাধিক ক্লায়েন্ট বাছুন। নির্দিষ্ট প্রকল্পের সব গ্রাহক নিতে সেটি বেছে ‘সব বাছুন’ চাপুন।",
  "there is nothing to choose from yet.": "বেছে নেওয়ার মতো কোনো রেকর্ড এখনো নেই।",
