  "everything in the admin panel - every project, unit, sale, payment, expense, owner, document record, plus all the public-site content you edit here (about/our story, founder profile, company policy, news, gallery captions, settings). saves straight to your device; nothing is kept on our server.": "প্রকল্প, ইউনিট, বিক্রয়, পেমেন্ট, ব্যয়, মালিক, নথির রেকর্ড ও এখানে সম্পাদনা করা পাবলিক সাইটের সব কনটেন্ট ব্যাকআপে থাকবে। ফাইল সরাসরি আপনার ডিভাইসে ডাউনলোড হবে।",
