  "restore from a backup": "ব্যাকআপ থেকে পুনরুদ্ধার করুন",
  "pick a backup .zip downloaded from this page - everything in it goes back to exactly where it came from automatically, no manual sorting needed.": "এই পেজ থেকে ডাউনলোড করা ব্যাকআপের .zip ফাইল বাছুন। এর তথ্য স্বয়ংক্রিয়ভাবে আগের জায়গাগুলোতে ফেরত যাবে।",
  "this replaces all current data with the backup's contents - anything added or changed since that backup was taken will be lost. this can't be undone. if unsure, download a fresh backup first.": "ব্যাকআপের তথ্য দিয়ে বর্তমান সব ডেটা প্রতিস্থাপিত হবে। ব্যাকআপের পর যা যোগ বা পরিবর্তন হয়েছে তা হারিয়ে যাবে। এই কাজ ফেরানো যাবে না। প্রয়োজন হলে আগে বর্তমান অবস্থার একটি নতুন ব্যাকআপ নিন।",
