  "open a customer's profile (client page → one client).": "ক্লায়েন্ট পোর্টাল → একজন ক্লায়েন্ট থেকে গ্রাহকের প্রোফাইল খুলুন।",
  "turn on their personal link, or set a phone login.": "ব্যক্তিগত লিংক চালু করুন অথবা ফোন দিয়ে লগইন সেট করুন।",
  "press the whatsapp button to send it.": "হোয়াটসঅ্যাপ বাটন দিয়ে লিংক পাঠান।",
