  "add phase": "ধাপ যোগ করুন",
  "vision & philosophy": "দৃষ্টিভঙ্গি ও দর্শন",
  "added": "যোগ হয়েছে",
  "visibility": "দেখানোর অবস্থা",
  "size": "আয়তন",
  "belongs to": "যার সঙ্গে যুক্ত",
  "new allocation": "নতুন বরাদ্দ",
  "total amount": "মোট পরিমাণ",
  "no owned units found in this project - nothing to allocate.": "এই প্রকল্পে কোনো মালিককে ইউনিট বরাদ্দ দেওয়া হয়নি। খরচ বণ্টনের জন্য আগে মালিক যোগ করুন।",
  "expenses couldn't be loaded. please try again.": "ব্যয়ের তথ্য লোড হয়নি। আবার চেষ্টা করুন।",
  "actual (manual)": "নিজে দেওয়া প্রকৃত খরচ",
  "total outstanding": "মোট বকেয়া",
  "outstanding contributions": "বকেয়া অবদান",
