  "press open - you land on the client app look part.": "খুলুন চাপলে ক্লায়েন্ট অ্যাপের চেহারা সেটিং খুলবে।",
  "choose a look and save. each client can still change it for themselves.": "পছন্দের চেহারা বেছে সেভ করুন। ক্লায়েন্ট নিজের জন্য সেটি বদলাতে পারবেন।",
  "the statements & notices studio: make notices, receipts and statements on letterhead.": "লেটারহেডে নোটিশ, রসিদ ও বিবরণী তৈরি করুন।",
  "choose the client and the paper, check the preview, send.": "ক্লায়েন্ট ও নথির ধরন বেছে প্রিভিউ যাচাই করে পাঠান।",
  "sends a message that appears in clients' app notifications.": "ক্লায়েন্ট অ্যাপের বিজ্ঞপ্তিতে দেখানোর জন্য বার্তা পাঠান।",
  "pick who gets it and write the message.": "প্রাপক বেছে বার্তা লিখুন।",
  "all notifications already sent.": "ইতিমধ্যে পাঠানো সব বিজ্ঞপ্তি।",
  "open one to see who got it.": "প্রাপক দেখতে একটি বিজ্ঞপ্তি খুলুন।",
  "every document that owners can see.": "মালিকেরা দেখতে পান এমন সব নথি।",
  "open one to edit or delete it.": "সম্পাদনা বা মুছতে নথিটি খুলুন।",
  "uploads a document for a client, project or the company.": "ক্লায়েন্ট, প্রকল্প বা কোম্পানির জন্য নথি আপলোড করুন।",
  "choose who it belongs to and upload the file.": "নথি যার সঙ্গে যুক্ত হবে তাকে বেছে ফাইল আপলোড করুন।",
  "records a payment a client made.": "ক্লায়েন্টের দেওয়া টাকা নথিভুক্ত করুন।",
