  "installments: due dates and what is overdue.": "কিস্তির শেষ তারিখ ও মেয়াদ পেরোনো কিস্তি দেখুন।",
  "open one to edit, or filter overdue ones.": "সম্পাদনা করতে কিস্তি খুলুন অথবা মেয়াদ পেরোনো কিস্তি ফিল্টার করুন।",
  "budgets and cost splits: how much each owner pays towards a project.": "বাজেট ও খরচ বণ্টনে দেখুন প্রকল্পে প্রতি মালিক কত দেবেন।",
  "open a budget to see each owner's share.": "মালিকদের অংশ দেখতে বাজেট খুলুন।",
  "creates a new budget split across owners.": "মালিকদের মধ্যে নতুনভাবে বাজেট ভাগ করুন।",
  "open a sale for its details and payments.": "বিস্তারিত ও পেমেন্ট দেখতে বিক্রয়টি খুলুন।",
