  "open a customer for profile, access link and payments.": "প্রোফাইল, প্রবেশের লিংক ও পেমেন্ট দেখতে গ্রাহকের নাম খুলুন।",
  "the list of shareholders.": "শেয়ারহোল্ডারদের তালিকা।",
  "open one for holdings and app access.": "শেয়ার ও অ্যাপের প্রবেশাধিকার দেখতে নাম খুলুন।",
  "adds a new shareholder.": "নতুন শেয়ারহোল্ডার যোগ করুন।",
  "the list of landowners and their agreements.": "জমির মালিক ও তাঁদের চুক্তির তালিকা।",
  "open one for agreements and app access.": "চুক্তি ও অ্যাপ প্রবেশাধিকার দেখতে নাম খুলুন।",
  "adds a new landowner.": "নতুন জমির মালিক যোগ করুন।",
  "the accounts that can sign in: staff and portal users.": "সাইন ইন করতে পারেন এমন কর্মী ও পোর্টাল ব্যবহারকারীর অ্যাকাউন্ট।",
  "open one to change access or role.": "প্রবেশাধিকার বা ভূমিকা বদলাতে অ্যাকাউন্ট খুলুন।",
  "blueprint ai: the rules and checker used to make floor-plan drawings the app can use.": "অ্যাপে ব্যবহারযোগ্য ফ্লোর প্ল্যান তৈরির নিয়ম ও যাচাইয়ের টুল।",
  "edit the prompts, or check a drawing.": "প্রম্পট সম্পাদনা করুন বা নকশা যাচাই করুন।",
  "the blueprint control panel: check plan drawings and fix problems.": "ব্লুপ্রিন্ট নিয়ন্ত্রণ প্যানেলে নকশা যাচাই ও সংশোধন করুন।",
  "review each drawing and correct it.": "প্রতিটি নকশা দেখে ভুল ঠিক করুন।",
  "blueprint distribution: which plans go to which building.": "কোন ভবনে কোন ব্লুপ্রিন্ট যাবে তা ঠিক করুন।",
  "assign the plans, then save.": "প্ল্যান বরাদ্দ করে সেভ করুন।",
  "watch simba run the whole panel": "সিম্বার মাধ্যমে পুরো প্যানেলের কাজ দেখুন",
  "adds a sample project, budget, expense, construction phase, customer, website project and listing, and news - then deletes them all.": "নমুনা প্রকল্প, বাজেট, ব্যয়, নির্মাণ ধাপ, গ্রাহক, পাবলিক প্রকল্প, সম্পত্তি ও সংবাদ তৈরি করে। শেষে নমুনাগুলো সরায়।",
  "create a new project": "নতুন প্রকল্প তৈরি করুন",
  "every field of the project form (simba can fill it in for you), then how to edit and delete a project.": "প্রকল্প ফর্মের প্রতিটি ঘর এবং প্রকল্প সম্পাদনা বা মুছতে হয় কীভাবে দেখুন।",
  "build buildings, floors and flats": "ভবন, তলা ও ফ্ল্যাট তৈরি করুন",
  "generate or add buildings and floors, open a flat, edit it, assign its owner, and how to delete one.": "ভবন ও তলা যোগ করুন। ফ্ল্যাট খুলে সম্পাদনা, মালিক বরাদ্দ ও মুছে ফেলার পদ্ধতি দেখুন।",
  "upload floor plans and blueprint types": "ফ্লোর প্ল্যান ও ব্লুপ্রিন্ট টাইপ আপলোড করুন",
  "upload the whole-floor drawing, mark every flat on it, check the live preview, and delete a plan.": "পুরো তলার নকশা দিন, ফ্ল্যাটগুলো চিহ্নিত করুন, প্রিভিউ দেখুন এবং প্ল্যান সরানোর পদ্ধতি শিখুন।",
  "add a customer and give app access": "গ্রাহক যোগ করে অ্যাপে প্রবেশাধিকার দিন",
  "every customer field (simba can fill it in), then their profile: edit, delete, and the personal link or phone login for the client app.": "গ্রাহক ফর্ম ও প্রোফাইলের তথ্য দেখুন। সম্পাদনা, ব্যক্তিগত লিংক ও ফোন দিয়ে লগইন পরিচালনা শিখুন।",
  "drag flats onto their owners, then check the result. without this, no one sees a flat in the app.": "ফ্ল্যাটটি মালিকের নামে টেনে দিয়ে ফল দেখুন। বরাদ্দ হলেই মালিক অ্যাপে ফ্ল্যাটটি দেখতে পাবেন।",
  "record a sale, installments and payments": "বিক্রয়, কিস্তি ও পেমেন্ট নথিভুক্ত করুন",
  "from the sale form to the installment plan, a payment, and a receipt - with delete explained.": "বিক্রয় ফর্ম, কিস্তি পরিকল্পনা, পেমেন্ট ও রসিদ তৈরির ধাপ। রেকর্ড মুছতে কী হয় তাও দেখুন।",
  "put a project on the website, with blueprints": "ব্লুপ্রিন্টসহ প্রকল্প ওয়েবসাইটে দিন",
  "every field of the website project form, the three blueprints, photos, map, featured - simba can do it and then delete it.": "পাবলিক প্রকল্প ফর্ম, তিনটি ব্লুপ্রিন্ট, ছবি, মানচিত্র ও বিশেষভাবে দেখানোর অপশন দেখুন।",
  "list a flat on the website": "ফ্ল্যাট ওয়েবসাইটে তালিকাভুক্ত করুন",
  "choose flat or whole building, fill the details and price, add photos and the floor plan - simba can do it and then delete it.": "ফ্ল্যাট বা পুরো ভবন বেছে বিবরণ, দাম, ছবি ও ফ্লোর প্ল্যান দিন। সিম্বা নমুনা তৈরি করে পরে সরাতে পারে।",
  "publish news and gallery photos": "সংবাদ ও গ্যালারির ছবি প্রকাশ করুন",
  "the news form field by field (simba can publish and delete a demo article), bulk photo upload, and deleting.": "সংবাদ ফর্ম, একসঙ্গে ছবি আপলোড ও রেকর্ড মুছতে হয় কীভাবে দেখুন।",
