  "set planned amounts, record what was spent, and split a shared cost among owners.": "পরিকল্পিত বাজেট ও প্রকৃত খরচ দিন এবং যৌথ খরচ মালিকদের মধ্যে ভাগ করুন।",
  "record expenses and buy materials": "ব্যয় ও সামগ্রী ক্রয় নথিভুক্ত করুন",
