  "construction phases and progress": "নির্মাণের ধাপ ও অগ্রগতি",
  "add a phase, track progress and dates, and delete one.": "ধাপ যোগ করুন, অগ্রগতি ও তারিখ দেখুন, এবং ধাপ সরানোর পদ্ধতি জানুন।",
  "add a staff member and set a role": "কর্মী যোগ করে ভূমিকা দিন",
