  "open each flat and enter its size, rooms and base price. without a price, sales and installments cannot work.": "প্রতিটি ফ্ল্যাট খুলে আকার, ঘর ও মূল মূল্য লিখুন। বিক্রয় ও কিস্তির জন্য মূল্য দিতে হবে।",
