  "money page: payments, installments, budgets, expenses and reports. most used on top.": "টাকা-পয়সা: পেমেন্ট, কিস্তি, বাজেট, ব্যয় ও প্রতিবেদন। সবচেয়ে বেশি ব্যবহৃত অপশন ওপরে।",
