  "help: the full written guide for every page.": "সহায়তা: সব পেজের লিখিত নির্দেশিকা।",
  "and i am always here, bottom right. press me for what to do next, what this page is, or to explain anything you click.": "নিচের ডান পাশে আমাকে পাবেন। পরের কাজ বা পেজের কাজ জানতে এবং কোনো বাটন বুঝতে আমাকে চাপুন।",
  "this is the new-project form. a project is the base of everything - buildings, flats, owners and money all hang under it.": "এটি নতুন প্রকল্পের ফর্ম। ভবন, ফ্ল্যাট, মালিক ও হিসাব সব এই প্রকল্পের সঙ্গে যুক্ত হবে।",
  "the project's name, shown in lists, reports and the client app.": "তালিকা, প্রতিবেদন ও গ্রাহকের অ্যাপে দেখানো প্রকল্পের নাম।",
  "a short unique code, used to tell projects apart.": "প্রকল্প আলাদা করে চেনার জন্য ছোট একটি অনন্য কোড।",
  "what the project is, in a few sentences.": "কয়েকটি বাক্যে প্রকল্পের বিবরণ দিন।",
