  "whether you are selling yet: not started, open or closed.": "বিক্রয় শুরু হয়নি, চলছে, নাকি বন্ধ তা বেছে নিন।",
  "the full address.": "পূর্ণ ঠিকানা।",
  "the city.": "শহর।",
  "what kind of project it is.": "প্রকল্পের ধরন।",
  "summary numbers only (buildings, floors, units, parking). the real buildings, floors and flats are added later in the units tab.": "এখানে ভবন, তলা, ইউনিট ও পার্কিংয়ের মোট সংখ্যা দিন। বিস্তারিত পরে ‘ইউনিট’ ট্যাবে যোগ করুন।",
