  "more pictures of the project.": "প্রকল্পের অতিরিক্ত ছবি।",
  "optional: the planned total cost. real budget lines are added later in project finance.": "পরিকল্পিত মোট খরচ দেওয়া ঐচ্ছিক। বিস্তারিত বাজেট পরে প্রকল্পের অর্থ বিভাগে যোগ করুন।",
  "when on, the project may appear on the public website. leave it off until the details are ready.": "চালু করলে প্রকল্প পাবলিক সাইটে দেখা যেতে পারে। তথ্য প্রস্তুত হলে চালু করুন।",
  "press create project. you land inside the new project, where the tabs are.": "‘প্রকল্প তৈরি করুন’ চাপুন। নতুন প্রকল্পের পেজ ও ট্যাবগুলো খুলবে।",
  "a project's page. edit reopens the same form to change anything.": "এটি প্রকল্পের পেজ। তথ্য বদলাতে ‘সম্পাদনা’ দিয়ে একই ফর্ম খুলুন।",
  "deletes the whole project.": "পুরো প্রকল্পটি মুছে যায়।",
  "the tabs run in the order you will use them: units, owners, distribute, parking, floor plans, construction, payments, materials, expenses, documents, reports, settings.": "ট্যাবের ক্রম: ইউনিট, মালিক, বরাদ্দ, পার্কিং, তলার নকশা, নির্মাণ, পেমেন্ট, উপকরণ, ব্যয়, নথি, প্রতিবেদন ও সেটিংস।",
  "now simba deletes the demo project it just made - and only that one.": "সিম্বা এখন তার তৈরি ডেমো প্রকল্পটি মুছবে।",
  "the units tab holds the structure: buildings, each with floors, each floor with flats.": "ইউনিট ট্যাবে ভবন, প্রতিটি ভবনের তলা ও তলার ফ্ল্যাট দেখা যায়।",
  "creates floors and flats in one go - the quickest way to set up a tall building.": "একসঙ্গে তলা ও ফ্ল্যাট তৈরি করে। উঁচু ভবনের কাঠামো দ্রুত যোগ করা যায়।",
  "adds one building by hand.": "একটি ভবন আলাদাভাবে যোগ করুন।",
  "adds one floor to a building.": "ভবনে একটি তলা যোগ করুন।",
  "each tile is a flat. click one to open its own page.": "প্রতিটি কার্ড একটি ফ্ল্যাট। তার পেজ খুলতে কার্ডে ক্লিক করুন।",
  "edit: the flat's number, size, rooms, facing, price and extra charges.": "সম্পাদনা: ফ্ল্যাটের নম্বর, আকার, ঘর, দিক, মূল্য ও বাড়তি চার্জ বদলান।",
  "ownership: give this flat to a customer, shareholder or landowner, or transfer it later. the change is recorded in its history.": "গ্রাহক, শেয়ারহোল্ডার বা জমির মালিককে ফ্ল্যাট দিন। পরে বদলালে ইতিহাসে রেকর্ড থাকবে।",
  "deletes this flat.": "এই ফ্ল্যাটটি মুছে যায়।",
  "floor plans: the whole floor of the building with every flat marked. in the client app the owner's own flat lights up on it.": "তলার নকশায় সব ফ্ল্যাট চিহ্নিত থাকে। গ্রাহকের অ্যাপে তাঁর নিজের ফ্ল্যাটটি আলাদা করে ফুটে উঠবে।",
  "upload the architect's whole-floor drawing. layout only: no background colour or border.": "স্থপতির পুরো তলার নকশা আপলোড করুন। শুধু লেআউট দিন, পটভূমির রং ও বর্ডার ছাড়াই।",
  "say which floors use this plan. leave it empty for the typical plan; use 0 for the ground floor.": "কোন তলায় এই নকশা ব্যবহার হবে বলুন। সাধারণ তলার জন্য ফাঁকা রাখুন, নিচতলার জন্য ০ দিন।",
  "choose how to mark a flat on the drawing.": "নকশায় ফ্ল্যাট চিহ্নিত করার পদ্ধতি বেছে নিন।",
  "draw the flat's outline, then name it exactly like its unit number, for example 1a.": "ফ্ল্যাটের সীমানা আঁকুন ও ইউনিট নম্বর অনুযায়ী নাম দিন, যেমন 1A।",
  "the live preview shows how the owner's home card will look, with their flat selected.": "লাইভ প্রিভিউতে মালিকের হোম কার্ডে তাঁর ফ্ল্যাটটি কেমন দেখাবে তা দেখা যায়।",
  "save. nothing is stored until you press it.": "‘সেভ’ চাপলে নকশাটি সংরক্ষিত হবে।",
