  "press create customer.": "‘গ্রাহক তৈরি করুন’ চাপুন।",
  "a customer's profile. edit changes the details above.": "গ্রাহকের প্রোফাইল। তথ্য বদলাতে ‘সম্পাদনা’ চাপুন।",
  "deletes this customer.": "এই গ্রাহককে মুছে দেয়।",
