  "or give them a phone and pin login instead of the link.": "লিংকের বদলে ফোন নম্বর ও পিন দিয়ে লগইনের ব্যবস্থাও করতে পারেন।",
  "now simba deletes the demo customer it just made - and only that one.": "সিম্বা এখন তার তৈরি ডেমো গ্রাহকটিকেই মুছবে।",
