  "choose the owner, then drag a flat onto them (or tap to assign). a flat can have one owner at a time.": "মালিক বেছে তাঁর ওপর ফ্ল্যাট টেনে ছাড়ুন অথবা বরাদ্দের জন্য চাপুন। এক সময়ে একটি ফ্ল্যাটের একজন মালিক থাকতে পারেন।",
  "owners: check who owns what and what each has paid. to change an owner later, use distribute or open the flat.": "মালিকানা ও পরিশোধিত টাকা দেখুন। মালিক বদলাতে বরাদ্দ বিভাগ বা ফ্ল্যাটের পেজ খুলুন।",
  "record sale: a sale ties a customer to a flat at an agreed price.": "বিক্রয় রেকর্ডে সম্মত মূল্যে ফ্ল্যাট ও ক্রেতাকে যুক্ত করা হয়।",
