export function translateAdminCopy(text: string): string {
  const key = text.trim().replace(/\s+/g, " ").replace(/[‘’]/g, "'").replace(/[–—]/g, "-").toLowerCase();
  const normalized = key.replace(/[“”]/g, '"').replace(/…/g, "...");
  const plain = normalized.replace(/\.{1,3}$/, "");
  const translated = getPhrase(key) ?? getPhrase(normalized) ?? getPhrase(plain) ?? getPhrase(`${plain}.`) ?? getCommonMessage(key);
  return translated ? text.replace(/\S(?:[\s\S]*\S)?/, () => translated) : text;
}

function getPhrase(key: string) {
  return Object.hasOwn(phrases, key) ? phrases[key] : undefined;
}

const commonMessages: ReadonlyArray<[RegExp, (label: string) => string]> = [
  [/^(.+) \(optional\)$/, (label) => `${label} (ঐচ্ছিক)`],
  [/^filter by (.+)$/, (label) => `${label} দিয়ে ফিল্টার করুন`],
  [/^(?:select|choose) (?:a |an |the )?(.+)$/, (label) => `${label} বাছুন`],
  [/^add (?:a |an |the )?(.+)$/, (label) => `${label} যোগ করুন`],
  [/^edit (?:a |an |the )?(.+)$/, (label) => `${label} সম্পাদনা করুন`],
  [/^view (?:a |an |the )?(.+)$/, (label) => `${label} দেখুন`],
  [/^delete (?:a |an |the )?(.+)$/, (label) => `${label} মুছুন`],
  [/^you don't have permission to view (?:this |the )?(.+)\.$/, (label) => `${label} দেখার অনুমতি আপনার নেই।`],
  [/^you don't have permission to (?:manage|edit) (?:this |the )?(.+)\.$/, (label) => `${label} পরিচালনার অনুমতি আপনার নেই।`],
  [/^no (.+) (?:yet|found)\.?$/, (label) => `কোনো ${label} পাওয়া যায়নি।`],
  [/^(.+) couldn't be loaded\. please try again\.$/, (label) => `${label} লোড হয়নি। আবার চেষ্টা করুন।`],
  [/^you don't have permission to (?:add|create) (.+)\.$/, (label) => `${label} যোগ করার অনুমতি আপনার নেই।`],
  [/^(?:this|that) (.+) no longer exists\.$/, (label) => `${label} আর পাওয়া যাচ্ছে না।`],
  [/^enter (?:a |an |the )?valid (.+)\.$/, (label) => `সঠিক ${label} লিখুন।`],
  [/^enter (?:a |an |the )?(.+)\.$/, (label) => `${label} লিখুন।`],
  [/^choose (?:a |an |the )?valid (.+)\.$/, (label) => `সঠিক ${label} বেছে নিন।`],
  [/^choose (?:a |an |the )?(.+)\.$/, (label) => `${label} বেছে নিন।`],
];

function getCommonMessage(key: string) {
  const minLength = /^(.+) must be at least (\d+) characters\.$/.exec(key);
  const field = minLength && getPhrase(minLength[1]);
  if (minLength && field) return `${field} অন্তত ${minLength[2]} অক্ষরের হতে হবে।`;

  for (const [pattern, format] of commonMessages) {
    const match = pattern.exec(key);
    const label = match && getPhrase(match[1]);
    if (label) return format(label);
  }
  return undefined;
}
